var n=`0968-bulgogi`;var t=`world-0968`;var s=`KR`;var a=`east-asia`;var o=4;var r=117;var g={en:`Bulgogi`,ua:`Пулькогі`};var l={en:`Bulgogi is a South Korea dish made with beef sirloin, asian pear, light soy sauce, garlic. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Пулькогі, страва кухні країни Південна Корея. Основні складники: яловичий сирлойн, азійська груша, світлий соєвий соус, часник. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`beef-sirloin`,750,`g`],[`asian-pear`,1,`pcs`],[`light-soy-sauce`,75,`ml`],[`brown-sugar`,40,`g`],[`garlic`,5,`clove`],[`toasted-sesame-oil`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 14 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 14 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:14,i:[[`yellow-onion`,220,`g`],[`carrot`,170,`g`],[`green-onion`,95,`g`],[`canola-oil`,35,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-sesame-seeds`,25,`g`]]}];var d={slug:n,id:t,country:`KR`,region:a,servings:4,minutes:117,title:g,text:l,steps:u};export{s as country,d as default,t as id,r as minutes,a as region,o as servings,n as slug,u as steps,l as text,g as title};